import os
import re
import json
import hmac
import hashlib
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32))
app.config['UPLOAD_DIR'] = '/var/app/uploads'
app.config['CONVERTED_DIR'] = '/var/app/converted'
app.config['OWNERSHIP_FILE'] = '/var/app/ownership.json'
app.config['MAX_CONTENT_LENGTH'] = 10 * 1024 * 1024

ALLOWED_EXTENSIONS = {'.pdf', '.docx', '.xlsx', '.pptx', '.odt', '.ods'}
ALLOWED_OUTPUT_FORMATS = {'pdf', 'html', 'txt', 'png'}


def _load_ownership():
    """Load the doc_id -> owner mapping"""
    try:
        with open(app.config['OWNERSHIP_FILE'], 'r') as fh:
            return json.load(fh)
    except (FileNotFoundError, ValueError):
        return {}


def _save_ownership(mapping):
    """Persist the doc_id -> owner mapping atomically"""
    os.makedirs(os.path.dirname(app.config['OWNERSHIP_FILE']), exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=os.path.dirname(app.config['OWNERSHIP_FILE']))
    try:
        with os.fdopen(fd, 'w') as fh:
            json.dump(mapping, fh)
        os.replace(tmp, app.config['OWNERSHIP_FILE'])
    except Exception:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise


def record_owner(doc_id, username):
    """Record that a document belongs to a user"""
    mapping = _load_ownership()
    mapping[doc_id] = username
    _save_ownership(mapping)


def user_owns_doc(doc_id, username):
    """Verify the given user owns the given document"""
    mapping = _load_ownership()
    return mapping.get(doc_id) == username


def verify_auth_token(token):
    """Verify HMAC-based auth token"""
    if not token or '.' not in token:
        return None
    parts = token.rsplit('.', 1)
    if len(parts) != 2:
        return None
    payload, signature = parts
    expected = hmac.new(app.config['SECRET_KEY'] if isinstance(app.config['SECRET_KEY'], bytes) else app.config['SECRET_KEY'].encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return None
    return payload


def get_current_user():
    """Extract authenticated user from request"""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return None
    token = auth_header[7:]
    return verify_auth_token(token)


def validate_filename(filename):
    """Validate uploaded filename for safety"""
    if not filename:
        return None
    # Remove any path separators
    filename = filename.replace('/', '').replace('\\', '')
    # Remove null bytes
    filename = filename.replace('\x00', '')
    # Check length
    if len(filename) > 200 or len(filename) < 3:
        return None
    # Must have allowed extension
    _, ext = os.path.splitext(filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return None
    # Only allow alphanumeric, dash, underscore, dot, space
    if not re.match(r'^[a-zA-Z0-9_.\- ]+$', filename):
        return None
    return filename


def validate_output_format(fmt):
    """Validate output format"""
    if fmt and fmt.lower() in ALLOWED_OUTPUT_FORMATS:
        return fmt.lower()
    return None


def generate_safe_id(username, filename):
    """Generate a deterministic safe ID for storage"""
    h = hashlib.sha256(f"{username}:{filename}".encode()).hexdigest()[:16]
    return h


def get_conversion_command(input_path, output_path, output_format):
    """Build the conversion command using LibreOffice"""
    cmd = [
        'libreoffice',
        '--headless',
        '--convert-to', output_format,
        '--outdir', os.path.dirname(output_path),
        input_path
    ]
    return cmd


def convert_document_worker(input_path, output_dir, output_format, safe_id):
    """Perform document conversion in a worker process"""
    # Use safe_id for output naming - never use user-controlled filenames
    output_filename = f"{safe_id}.{output_format}"
    output_path = os.path.join(output_dir, output_filename)

    # Build and execute conversion command
    cmd = get_conversion_command(input_path, output_path, output_format)

    try:
        result = subprocess.run(
            cmd,
            timeout=60,
            capture_output=True,
            cwd=output_dir
        )
        if result.returncode != 0:
            return None, f"Conversion failed: {result.stderr.decode('utf-8', errors='replace')[:200]}"

        # Find the actual output file
        expected_output = os.path.join(output_dir, output_filename)
        if os.path.isfile(expected_output):
            return expected_output, None

        # Try to find any file with the right extension
        for f in os.listdir(output_dir):
            if f.endswith(f'.{output_format}'):
                return os.path.join(output_dir, f), None

        return None, "Output file not found"
    except subprocess.TimeoutExpired:
        return None, "Conversion timed out"
    except Exception as e:
        return None, str(e)


def generate_thumbnail(input_path, output_dir, safe_id):
    """Generate a thumbnail preview using ImageMagick"""
    thumb_path = os.path.join(output_dir, f"{safe_id}_thumb.png")

    # Use list form to avoid shell injection
    cmd = [
        'convert',
        f'{input_path}[0]',
        '-thumbnail', '200x200',
        thumb_path
    ]

    try:
        subprocess.run(cmd, shell=False, timeout=30, capture_output=True)
        if os.path.isfile(thumb_path):
            return thumb_path
    except Exception:
        pass
    return None


@app.route('/api/v1/upload', methods=['POST'])
def upload_document():
    """Upload a document for conversion"""
    user = get_current_user()
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401

    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    filename = validate_filename(file.filename)
    if not filename:
        return jsonify({'error': 'Invalid filename'}), 400

    # Generate safe storage path
    safe_id = generate_safe_id(user, filename)
    _, ext = os.path.splitext(filename)
    storage_path = os.path.join(app.config['UPLOAD_DIR'], f"{safe_id}{ext}")

    # Save file
    os.makedirs(app.config['UPLOAD_DIR'], exist_ok=True)
    file.save(storage_path)

    # Record ownership so only this user can access the document later
    record_owner(safe_id, user)

    return jsonify({
        'id': safe_id,
        'filename': filename,
        'status': 'uploaded'
    }), 201


@app.route('/api/v1/convert/<doc_id>', methods=['POST'])
def convert_document(doc_id):
    """Convert an uploaded document to another format"""
    user = get_current_user()
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401

    # Validate doc_id format
    if not re.match(r'^[a-f0-9]{16}$', doc_id):
        return jsonify({'error': 'Invalid document ID'}), 400

    # Enforce ownership - prevent IDOR
    if not user_owns_doc(doc_id, user):
        return jsonify({'error': 'Access denied'}), 403

    output_format = validate_output_format(request.json.get('format') if request.json else None)
    if not output_format:
        return jsonify({'error': 'Invalid output format'}), 400

    # Find the uploaded file
    upload_dir = app.config['UPLOAD_DIR']
    input_file = None

    for f in os.listdir(upload_dir):
        if f.startswith(doc_id):
            input_file = os.path.join(upload_dir, f)
            break

    if not input_file or not os.path.isfile(input_file):
        return jsonify({'error': 'Document not found'}), 404

    # Create output directory
    output_dir = os.path.join(app.config['CONVERTED_DIR'], doc_id)
    os.makedirs(output_dir, exist_ok=True)

    # Perform conversion - use safe_id for output naming
    output_path, error = convert_document_worker(
        input_file, output_dir, output_format, doc_id
    )

    if error:
        return jsonify({'error': error}), 500

    return jsonify({
        'id': doc_id,
        'output': os.path.basename(output_path),
        'status': 'converted'
    }), 200


@app.route('/api/v1/thumbnail/<doc_id>', methods=['POST'])
def create_thumbnail(doc_id):
    """Generate thumbnail for a document"""
    user = get_current_user()
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401

    if not re.match(r'^[a-f0-9]{16}$', doc_id):
        return jsonify({'error': 'Invalid document ID'}), 400

    # Enforce ownership - prevent IDOR
    if not user_owns_doc(doc_id, user):
        return jsonify({'error': 'Access denied'}), 403

    # Find the uploaded file
    upload_dir = app.config['UPLOAD_DIR']
    input_file = None

    for f in os.listdir(upload_dir):
        if f.startswith(doc_id):
            input_file = os.path.join(upload_dir, f)
            break

    if not input_file or not os.path.isfile(input_file):
        return jsonify({'error': 'Document not found'}), 404

    # Create output directory
    output_dir = os.path.join(app.config['CONVERTED_DIR'], doc_id)
    os.makedirs(output_dir, exist_ok=True)

    # Generate thumbnail using safe_id for naming
    thumb_path = generate_thumbnail(input_file, output_dir, doc_id)

    if not thumb_path:
        return jsonify({'error': 'Thumbnail generation failed'}), 500

    return jsonify({
        'id': doc_id,
        'thumbnail': os.path.basename(thumb_path),
        'status': 'generated'
    }), 200


@app.route('/api/v1/download/<doc_id>/<filename>', methods=['GET'])
def download_file(doc_id, filename):
    """Download a converted file"""
    user = get_current_user()
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401

    if not re.match(r'^[a-f0-9]{16}$', doc_id):
        return jsonify({'error': 'Invalid document ID'}), 400

    # Enforce ownership - prevent IDOR
    if not user_owns_doc(doc_id, user):
        return jsonify({'error': 'Access denied'}), 403

    # Sanitize filename
    safe_name = secure_filename(filename)
    if not safe_name:
        return jsonify({'error': 'Invalid filename'}), 400

    file_path = os.path.join(app.config['CONVERTED_DIR'], doc_id, safe_name)

    # Verify path is within converted directory
    real_path = os.path.realpath(file_path)
    base_path = os.path.realpath(app.config['CONVERTED_DIR'])
    if not real_path.startswith(base_path + '/'):
        return jsonify({'error': 'Access denied'}), 403

    if not os.path.isfile(real_path):
        return jsonify({'error': 'File not found'}), 404

    return send_file(real_path)


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
